public final class Order {
    private final OrderId id;
    private final CustomerId customer;
    private Order(OrderId id, CustomerId customer) { this.id = id; this.customer = customer; }
    public static Order fromCart(Cart cart, Instant now) {
        if (cart.isEmpty()) throw new DomainException("empty cart");
        return new Order(OrderId.newId(), cart.customerId());
    }
    static Order rehydrate(OrderId id, CustomerId customer) { return new Order(id, customer); }
}

