private static final Map<String, Supplier<Payment>> CREATORS = Map.of(
    "card", CardPayment::new,
    "sepa", SepaPayment::new);

static Payment create(String kind, RawPayment raw) {
    Supplier<Payment> creator = CREATORS.get(kind);
    if (creator == null) throw new DomainException("unknown payment kind: " + kind);
    return creator.get();
}

@Configuration
class OrderFactories {
    @Bean
    OrderFactory orderFactory(CustomerRepository customers, Clock clock) {
        return cart -> Order.fromCart(cart, customers.require(cart.customerId()), clock.instant());
    }
}
